Recipe "chaser" for this kit3d.js game: enemies (assets/enemy.glb, a red ball until it exists) that appear around the player and chase it; touching one calls hurt() from the lives recipe, or ends the round.
Paste each part into game.js with file_edit. It uses g.player.

--- 1. top of game.js, after the other let/const lines ---
let chasers;
let chaserTimer;
function addChaser(g) {
  const a = Kit.rand(0, Math.PI * 2);
  const e = Kit.model('assets/enemy.glb', Kit.shape.sphere(0.5, '#e53935'));
  e.position.set(g.player.position.x + Math.cos(a) * 18, 0, g.player.position.z + Math.sin(a) * 18);
  e.size = { w: 0.9, h: 0.9, d: 0.9 };
  e.vel = new THREE.Vector3();
  chasers.push(e);
}

--- 2. inside init(g), at the end (after g.player is made) ---
chasers = [];
chaserTimer = 2;

--- 3. inside update(g, dt), at the end ---
chaserTimer -= dt;
if (chaserTimer <= 0 && chasers.length < 8) { addChaser(g); chaserTimer = 4; }
for (const e of chasers) {
  const to = new THREE.Vector3(g.player.position.x - e.position.x, 0, g.player.position.z - e.position.z).normalize();
  e.vel.x = to.x * 3;
  e.vel.z = to.z * 3;
  Kit.move(e, dt);
  Kit.face(e, to, dt);
}
if (chasers.some((e) => Kit.near(g.player, e, 1.1))) {
  if (typeof hurt === 'function') hurt(); else Kit.gameOver();
}

