import { Kit, THREE } from './kit3d.js';

const TUNING = {
  speed: 6,          // walking speed (m/s)
  jump: 9,
};

let coins;
function addCoin(g) {
  const p = g.player.position;
  const c = Kit.cylinder(0.35, 0.08, '#ffc83d', p.x + Kit.rand(-15, 15), 0.8, p.z + Kit.rand(-15, 15));
  c.rotation.z = Math.PI / 2;
  coins.push(c);
}
const TIME_LIMIT = 60; // seconds
let timeLeft;
// Make the model first, e.g. make_model {"name": "tree", "path": "assets/tree.glb", "parts": [...]}
const SCENERY = 'assets/tree.glb';
// RECIPE TOP

function init(g) {
  Kit.ground(60, '#7cc46a');
  Kit.solid(Kit.box(2, 1, 2, '#8d9096', 5, 0, -5)); // something to jump on
  g.player = Kit.model('assets/player.glb', Kit.shape.box(0.8, 1.8, 0.8, '#3366ff'));
  g.player.size = { w: 0.8, h: 1.8, d: 0.8 };
  g.player.vel = new THREE.Vector3();
  coins = [];
  for (let i = 0; i < 8; i++) addCoin(g);
  timeLeft = TIME_LIMIT;
  for (let i = 0; i < 12; i++) {
    const s = Kit.model(SCENERY, Kit.shape.cone(1, 2.5, '#2e7d32'));
    s.position.set(Kit.rand(-25, 25), 0, Kit.rand(-25, 25));
    if (s.position.length() < 5) s.position.x += 8; // keep the start clear
    s.rotation.y = Kit.rand(0, Math.PI * 2);
    Kit.solid(s);
  }
  // RECIPE INIT
}

function update(g, dt) {
  const p = g.player;
  const dir = Kit.moveInput();
  p.vel.x = dir.x * TUNING.speed;
  p.vel.z = dir.z * TUNING.speed;
  if (Kit.pressed('jump') && p.onGround) { p.vel.y = TUNING.jump; Kit.sfx('jump'); }
  Kit.move(p, dt);
  Kit.face(p, dir, dt);
  Kit.walk(p, p.onGround ? dir.length() : 0);
