    const p = g.player;
    const s = Kit.sphere(0.15, '#ffeb3b', p.position.x, p.position.y + 1, p.position.z);
    s.vel = new THREE.Vector3(Math.sin(p.rotation.y), 0, Math.cos(p.rotation.y)).multiplyScalar(25); // models face +z
