{"path":"game.js","content":"// Blank 3D game: a character that walks and jumps on a ground. Build any 3D game from here. Built on kit3d.js.
// init(g) builds the world for each round, update(g, dt) moves things. The hero is assets/player.glb:
// to change how it looks, make a new model with make_model at that path (no code change needed).
import { Kit, THREE } from './kit3d.js';

const TUNING = {
  speed: 6,          // walking speed (m/s)
  jump: 9,
};

let movers;
let coins;
function addCoin(g) {
  const p = g.player.position;
  const c = Kit.cylinder(0.35, 0.08, '#ffc83d', p.x + Kit.rand(-15, 15), 0.8, p.z + Kit.rand(-15, 15));
  c.rotation.z = Math.PI / 2;
  coins.push(c);
}
let lives;
let hurtTimer;
// Call hurt() when something hits the player, instead of Kit.gameOver().
function hurt() {
  if (hurtTimer > 0) return;
  lives -= 1;
  hurtTimer = 1.5;
  Kit.sfx('hit');
  Kit.shake(0.3);
  if (lives <= 0) Kit.gameOver();
}
// RECIPE TOP

function init(g) {
  Kit.ground(60, '#7cc46a');
  Kit.solid(Kit.box(2, 1, 2, '#8d9096', 5, 0, -5)); // something to jump on
  g.player = Kit.model('assets/player.glb', Kit.shape.box(0.8, 1.8, 0.8, '#3366ff'));
  g.player.size = { w: 0.8, h: 1.8, d: 0.8 };
  g.player.vel = new THREE.Vector3();
  movers = [];
  for (let i = 0; i < 3; i++) {
    const m = Kit.box(3, 0.5, 3, '#ff8a65', -6 + i * 6, 1 + i, -10 - i * 4);
    m.base = m.position.clone();
    m.phase = i * 2;
    Kit.solid(m, true); // true = it moves
    movers.push(m);
  }
  coins = [];
  for (let i = 0; i < 8; i++) addCoin(g);
  lives = 3;
  hurtTimer = 0;
  // RECIPE INIT
}

function update(g, dt) {
  const p = g.player;
  const dir = Kit.moveInput();
  p.vel.x = dir.x * TUNING.speed;
  p.vel.z = dir.z * TUNING.speed;
  if (Kit.pressed('jump') && p.onGround) { p.vel.y = TUNING.jump; Kit.sfx('jump'); }
  Kit.move(p, dt);
  Kit.face(p, dir, dt);
  Kit.walk(p, p.onGround ? dir.length() : 0);
  for (const m of movers) {
    m.position.x = m.base.x + Math.sin(g.time * 0.8 + m.phase) * 3;
    m.position.y = m.base.y + Math.sin(g.time * 1.2 + m.phase) * 0.8;
  }
  for (const c of coins) {
    c.rotation.y += dt * 3;
    if (!c.taken && Kit.near(g.player, c, 1.4)) {
      c.taken = true;
      Kit.remove(c);
      Kit.addScore(1);
      Kit.sfx('coin');
      Kit.burst(c.position, '#ffc83d');
    }
  }
  coins = coins.filter((c) => !c.taken);
  if (coins.length < 4) addCoin(g);
  hurtTimer -= dt;
  g.player.visible = hurtTimer <= 0 || Math.floor(g.time * 10) % 2 === 0;
  Kit.hud('Lives ' + lives, 'lives');
  // RECIPE UPDATE
}

Kit.start({
  title: document.title,
  hint: 'WASD or arrows to move, Space to jump. Press Space or click to start',
  camera: 'third',
  init,
  update,
  debug: (g) => ({ onGround: !!g.player.onGround }),
});
"}

