// to change how it looks, make a new model with make_model at that path (no code change needed).
import { Kit, THREE } from './kit3d.js';

const TUNING = {
  speed: 6,          // walking speed (m/s)
  jump: 9,
};

const NODES = []; // trees and rocks the player can hit
const inv = { wood: 0, stone: 0, food: 0 };
const power = { tree: 1, rock: 1 }; // the craft recipe raises these when tools are made
function showInv() { Kit.hud(`Wood ${inv.wood}   Stone ${inv.stone}`, 'inv'); }
const tools = { hatchet: false, pickaxe: false };
function showCraft() { Kit.hud(`1 Hatchet (5 wood)${tools.hatchet ? ' made' : ''}   2 Pickaxe (3 wood, 5 stone)${tools.pickaxe ? ' made' : ''}`, 'craft'); }
// RECIPE TOP

function init(g) {
  Kit.ground(60, '#7cc46a');
  Kit.solid(Kit.box(2, 1, 2, '#8d9096', 5, 0, -5)); // something to jump on
  g.player = Kit.model('assets/player.glb', Kit.shape.box(0.8, 1.8, 0.8, '#3366ff'));
  g.player.size = { w: 0.8, h: 1.8, d: 0.8 };
  g.player.vel = new THREE.Vector3();
  NODES.length = 0;
  inv.wood = 0; inv.stone = 0; inv.food = 0;
  for (let i = 0; i < 18; i++) {
    const kind = i % 3 === 2 ? 'rock' : 'tree';
    const n = Kit.group(Kit.rand(-28, 28), 0, Kit.rand(-28, 28));
    if (n.position.length() < 5) n.position.x += 9; // keep the start clear
    if (kind === 'tree') {
      n.add(Kit.shape.cylinder(0.3, 2, '#6d4c2f'));
      const leaves = Kit.shape.cone(1.3, 2.6, '#2e7d32');
      leaves.position.y = 1.6;
      n.add(leaves);
    } else {
      n.add(Kit.shape.sphere(0.9, '#8d9096'));
    }
    n.kind = kind;
    n.hp = kind === 'tree' ? 4 : 5;
    Kit.solid(n);
    NODES.push(n);
  }
  showInv();
  tools.hatchet = false; tools.pickaxe = false;
  power.tree = 1; power.rock = 1;
  showCraft();
  // RECIPE INIT
}

function update(g, dt) {
  const p = g.player;
  const dir = Kit.moveInput();
  p.vel.x = dir.x * TUNNING.speed;
  p.vel.z = dir.z * TUNING.speed;
  if (Kit.pressed('jump') && p.onGround) { p.vel.y = TUNING.jump; Kit.sfx('jump'); }
  Kit.move(p, dt);
  Kit.face(p, dir, dt);
  Kit.walk(p, p.onGround ? dir.length() : 0);
  if (Kit.pressed('action')) {
    const n = NODES.find((o) => Kit.near(g.player, o, 2.4));
    if (n) {
      const res = n.kind === 'tree' ? 'wood' : 'stone';
      n.hp -= power[n.kind];
      inv[res] += power[n.kind];
      Kit.sfx('hit');
      Kit.burst(n.position.clone().setY(1), n.kind === 'tree' ? '#8d6e63' : '#b0b4ba');
      if (n.hp <= 0) { inv[res] += 2; Kit.remove(n); NODES.splice(NODES.indexOf(n), 1); Kit.sfx('coin'); }
      showInv();
    }
  }
  if (Kit.key('Digit1') && !tools.hatchet && inv.wood >= 5) {
    inv.wood -= 5; tools.hatchet = true; power.tree = 2; Kit.sfx('power'); showInv(); showCraft();
  }
  if (Kit.key('Digit2') && !tools.pickaxe && inv.wood >= 3 && inv.stone >= 5) {
    inv.wood -= 3; inv.stone -= 5; tools.pickaxe = true; power.rock = 2; Kit.sfx('power'); showInv(); showCraft();
  }
  // RECIPE UPDATE
}

Kit.start({
  title: document.title,
  hint: 'WASD or arrows to move, Space to jump. Press Space or click to start',
  camera: 'third',
  init,
  update,
  debug: (g) => ({ onGround: !!g.player.onGround }),
});

